def is_N_position(n, N, memo):
    # memo stores True for N-position, False for P-position
    if n in memo:
        return memo[n]

    # 1. Check move n -> n+1
    next_plus_1 = n + 1
    is_winning_plus_1 = False
    if next_plus_1 <= N:
        if next_plus_1 == N:
            is_winning_plus_1 = True  # Immediate win
        elif not is_N_position(next_plus_1, N, memo):
            is_winning_plus_1 = True  # Move leads to a P-position

    # 2. Check move n -> 2n
    next_times_2 = 2 * n
    is_winning_times_2 = False
    if next_times_2 <= N:
        if next_times_2 == N:
            is_winning_times_2 = True  # Immediate win
        elif not is_N_position(next_times_2, N, memo):
            is_winning_times_2 = True  # Move leads to a P-position

    # n is an N-position if at least one move leads to a P-position (or N)
    result = is_winning_plus_1 or is_winning_times_2
    memo[n] = result
    return result

def check_type_B(N):
    # N is Type B if 1 is a P-position (i.e., is_N_position(1, N) is False)
    if N <= 1:
        return False

    # Initialize memoization structure (we only need to store results for 1 to N-1)
    memo = {}

    # We call the recursive function for n=1
    return not is_N_position(1, N, memo)

# Search for the least N > 400 such that N is Type B
N_start = 401
N_found = None
count = 0
while N_found is None and count < 500: # Safety break
    if check_type_B(N_start):
        N_found = N_start
    else:
        count += 1
    N_start += 1

print(f"Least Type B number N > 400 found: {N_found}")

